hYE;EACE,aAAA;EACA,YAAA;EACA,sBAAA;EACA,mBAAA;EACA,8BAAA;EACA,SAAA;ALkYJ;;AK9XA;EACE,gBAAA;ALiYF;AKhYE;EACE,iBAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;ALkYJ;;AK9XA;EJhDI,uCAAA;EACA,gBIgD+B;EJ/C/B,kBAAA;EACA,cCJQ;EDKR,eI6CyB;EAC3B,kBAAA;ALqYF;;AKlYA;EJrDI,uCAAA;EACA,gBIqDkC;EJpDlC,kBAAA;EACA,YCHW;EDIX,eIkD4B;ALyYhC;;AM9bI;EACI,UAAA;ANicR;;AM7bA;EACI,eAAA;ANgcJ;;AM7bA;EACI,aAAA;EACA,mBAAA;EACA,SAAA;EACA,eAAA;ANgcJ;;AM7bA;ELjBI,uCAAA;EACA,gBKiBoC;ELhBpC,kBAAA;EACA,YCHW;EDIX,eKc8B;ANoclC;;AMhcI;ELtBA,uCAAA;EACA,gBKsBwC;ELrBxC,kBAAA;EACA,YCHW;EDIX,eKmBkC;ANuctC;AMrcQ;EACI,UJzBC;AFgeb;;AOleA;EACE,aAAA;EACA,4DAAA;EACA,SAAA;EACA,gBAAA;APqeF;;AOjeE;EACE,kBAAA;APoeJ;AOneK;ENTD,uCAAA;EACA,gBMSsC;ENRtC,kBAAA;EACA,YCHW;EDIX,eMMgC;APyepC;AOveM;EACE,ULZK;AFqfb;AOpeE;EACE,aAAA;EACA,sBAAA;EACA,QAAA;APseJ;;AQlfA;EACE,aAAA;EACA,qBAAA;EACA,SAAA;EACA,uBAAA;ARqfF;;AQlfA;EPhBI,uCAAA;EACA,gBOgBkC;EPflC,kBAAA;EACA,YCHW;EDIX,eOa4B;EAC9B,kBAAA;ARyfF","file":"advertisement.css","sourcesContent":["\n.filter {\n    padding-top: 30px;\n}\n\n.filter__list {\n    border-top: 1px solid $gray;\n    padding-top: 5px;\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\n    align-items: center;\n    justify-items: center;\n    gap: 5px;\n}\n\n.filter__list-item {\n    & a {\n        display: inline-block;\n        text-align: center;  \n        @include fonts($mainColor, 16px, 400);\n\n        &:hover{\n            color: $colorHover;\n        }\n\n        & span {\n            color:#545454;\n        }\n    }\n}",".filter {\n  padding-top: 30px;\n}\n\n.filter__list {\n  border-top: 1px solid #D4D4D4;\n  padding-top: 5px;\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\n  align-items: center;\n  justify-items: center;\n  gap: 5px;\n}\n\n.filter__list-item a {\n  display: inline-block;\n  text-align: center;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 16px;\n}\n.filter__list-item a:hover {\n  color: red;\n}\n.filter__list-item a span {\n  color: #545454;\n}\n\n.sort {\n  display: flex;\n  align-items: center;\n  gap: 15px;\n  margin-top: 15px;\n  margin-bottom: 15px;\n  flex-wrap: wrap;\n}\n\n.sort__ads {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.sort__ads span {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 500;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n\n.sort__type-list {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.sort__type-list li {\n  cursor: pointer;\n}\n\n.sorted__output {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.sorted__output a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.sorted__output p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.sorted__output-list {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.sorted__output-list li {\n  opacity: 0.5;\n  border: 1px solid black;\n  padding: 5px;\n  color: black;\n  cursor: pointer;\n}\n\n.sorted__by {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.sorted__by p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.sorted__by-list {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.sorted__by-list-item {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.sorted__by-list-item a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  cursor: pointer;\n}\n.sorted__by-list-item a:hover {\n  color: red;\n}\n\n.sorted__by-list-item-img {\n  max-width: 15px;\n  max-height: 15px;\n}\n.sorted__by-list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n@media (max-width: 992px) {\n  .sort {\n    justify-content: center;\n  }\n}\n.advertisement__list {\n  flex: 1 1 680px;\n}\n\n.default__item .advertisement__list-item {\n  display: flex;\n  gap: 40px;\n  padding: 5px;\n  border-bottom: 1px solid #D4D4D4;\n}\n.default__item ~ .vip__wrap {\n  flex: 1 0 250px;\n}\n.default__item .advertisement__list-item-img {\n  display: block;\n  max-width: 180px;\n  max-height: 140px;\n  flex: 0 1 140px;\n}\n.default__item .advertisement__list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__list-item-about {\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  position: relative;\n}\n.default__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.default__item .advertisement__list-item:has(.advertisement__list-item-action) .advertisement__list-item-about-favorites {\n  bottom: 25px;\n}\n.default__item .advertisement__list-item-title {\n  align-self: flex-start;\n}\n.default__item .advertisement__list-item-title a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n.default__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.default__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-action {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  align-self: flex-end;\n}\n.default__item .advertisement__list-item-action li {\n  max-width: 18px;\n  max-height: 18px;\n}\n.default__item .advertisement__list-item-action li img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__favorites-active {\n  background: url(../img/favorite_yes.png) no-repeat center/cover;\n}\n\n.second__item {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 10px 15px;\n  flex: 1 1 auto;\n}\n.second__item .advertisement__list-item {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 8px;\n  border: 1px solid #D4D4D4;\n  border-radius: 7px;\n}\n.second__item ~ .vip__wrap {\n  flex: 0 0 250px;\n}\n.second__item .advertisement__list-item-img {\n  display: block;\n}\n.second__item .advertisement__list-item-img img {\n  background: #fff;\n  max-height: 140px;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  object-position: center;\n}\n.second__item .advertisement__list-item-title a {\n  display: block;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 180px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 16px;\n}\n.second__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.second__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n  margin: 5px 0;\n}\n.second__item .advertisement__list-item-about-text-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.second__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n}\n.second__item .advertisement__list-item-about-text-list li:nth-child(1) {\n  display: none;\n}\n.second__item .advertisement__list-item-about-text-list li:nth-child(2) {\n  display: none;\n}\n.second__item .advertisement__list-item-action {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 10px;\n}\n.second__item .advertisement__list-item-action li {\n  max-width: 18px;\n  max-height: 18px;\n}\n.second__item .advertisement__list-item-action li img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.second__item .advertisement__list-item-about {\n  position: relative;\n}\n.second__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.second__item .advertisement__favorites-active {\n  background: url(../img/favorite_yes.png) no-repeat center/cover;\n}\n\n@media (max-width: 992px) {\n  .default__item {\n    flex: 1 1 auto;\n  }\n  .default__item ~ .vip__wrap {\n    flex: 1 0 250px;\n  }\n  .default__item .advertisement__list-item {\n    gap: 15px;\n    flex-direction: column;\n  }\n  .default__item .advertisement__list-item-img {\n    max-width: none;\n    max-height: none;\n    flex: initial;\n  }\n  .default__item .advertisement__list-item-img img {\n    max-height: 400px;\n  }\n  .default__item .advertisement__list-item-about::before {\n    top: initial;\n    bottom: 0;\n    right: 10px;\n    left: initial;\n  }\n  .second__item ~ .vip__wrap {\n    flex: 1 0 250px;\n  }\n}\n.active__item {\n  background: #FFFFCA;\n}\n\n.vip__wrap {\n  flex: 1 0 220px;\n}\n\n.vip__title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: white;\n  font-size: 18px;\n  padding: 10px;\n  text-align: center;\n  background: #ff6163;\n}\n\n.vip__list {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  align-items: stretch;\n  gap: 15px;\n}\n.vip__list li {\n  display: flex;\n  flex-direction: column;\n}\n\n.vip__list-item {\n  padding: 15px 30px;\n  border: 1px solid #ff6163;\n  flex: 1 1 auto;\n  height: 100%;\n}\n.vip__list-item a {\n  display: flex;\n  height: 100%;\n  flex-direction: column;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.vip__list-item-img {\n  max-width: 187px;\n}\n.vip__list-item-img img {\n  max-height: 187px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.vip__list-item-title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n  text-align: center;\n}\n\n.vip__list-item-district {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 13px;\n}\n\n.crumbs ~ .filter {\n  padding: 0;\n}\n\n.crumbs__wrapper {\n  padding: 15px 0;\n}\n\n.crumbs__list {\n  display: flex;\n  align-items: center;\n  gap: 15px;\n  flex-wrap: wrap;\n}\n\n.crumbs__list-item-dots {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.crumbs__list-item a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.crumbs__list-item a:hover {\n  color: red;\n}\n\n.more {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 20px;\n  margin-top: 20px;\n}\n\n.more__item h2 {\n  margin-bottom: 5px;\n}\n.more__item h2 a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n.more__item h2 a:hover {\n  color: red;\n}\n.more__item ul {\n  display: flex;